#!/usr/bin/env python3
"""Build the portable Podcat tutorial from canonical presets and the user's photos."""
import base64
import io
import json
from pathlib import Path
from PIL import Image, ImageOps

book = Path(__file__).resolve().parents[1]
repo = book.parents[1]

def photo(path, width=1100):
    im = ImageOps.exif_transpose(Image.open(path)).convert('RGB')
    im.thumbnail((width, width))
    stream = io.BytesIO()
    im.save(stream, format='JPEG', quality=82, optimize=True)
    return 'data:image/jpeg;base64,' + base64.b64encode(stream.getvalue()).decode()

data = json.loads((book / 'presets.json').read_text())
